/**
 * Incident Service
 */

import { ValidationError, NotFoundError } from '../domain/errors/index.js';
import { IIncidentRepository, ICreateIncidentDTO } from '../domain/repositories/IIncidentRepository.js';
import { RealTimeService } from './RealTimeService.js';

export class IncidentService {
  constructor(
    private readonly incidentRepository: IIncidentRepository,
    private readonly realTimeService: RealTimeService
  ) {}

  async reportIncident(data: ICreateIncidentDTO) {
    if (!data.title) throw new ValidationError('Title is required');
    if (!data.description) throw new ValidationError('Description is required');

    const incident = await this.incidentRepository.create(data);

    // Notify supervisors via real-time service
    // (Actual notification logic would go here)

    return incident;
  }

  async getIncident(id: number) {
    const incident = await this.incidentRepository.findById(id);
    if (!incident) throw new NotFoundError(`Incident with ID ${id} not found`);
    return incident;
  }

  async updateStatus(id: number, status: string, userId: number) {
    const incident = await this.getIncident(id);
    const updateData: any = { status };

    if (status === 'resolved') updateData.resolved_at = new Date();
    if (status === 'closed') updateData.closed_at = new Date();

    const updated = await this.incidentRepository.update(id, updateData);
    await this.incidentRepository.addComment(id, userId, `Status changed to ${status}`);
    
    return updated;
  }

  async assignIncident(id: number, assigneeId: number, userId: number) {
    const updated = await this.incidentRepository.update(id, { assigned_to: assigneeId });
    await this.incidentRepository.addComment(id, userId, `Incident assigned to user ${assigneeId}`);
    return updated;
  }

  async addComment(id: number, userId: number, comment: string) {
    return this.incidentRepository.addComment(id, userId, comment);
  }

  async addEvidence(id: number, data: any) {
    return this.incidentRepository.addEvidence(id, data);
  }

  async listIncidents(options: any = {}) {
    return this.incidentRepository.findAll(options);
  }
}

let instance: IncidentService | null = null;

export function initializeIncidentService(repo: IIncidentRepository, rt: RealTimeService): IncidentService {
  instance = new IncidentService(repo, rt);
  return instance;
}

export function getIncidentService(): IncidentService {
  if (!instance) throw new Error('IncidentService not initialized');
  return instance;
}
